import random
from itertools import combinations

def girth_at_least_8(adj, n):
    # BFS from each vertex to detect short cycles
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nq = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        if dist[v] < 4:
                            nq.append(v)
                    elif v != parent[u]:
                        # found cycle of length dist[u]+dist[v]+1
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len < 8:
                            return False
            queue = nq
    return True

