import random
from itertools import combinations

def girth(edges, n):
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    best = 100
    for s in range(n):
        dist = {s:0}
        parent = {s:-1}
        q = [s]
        while q:
            nq = []
            for u in q:
                for v in adj[u]:
                    if v not in dist:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        nq.append(v)
                    elif parent[u] != v:
                        best = min(best, dist[u]+dist[v]+1)
            q = nq
    return best

# Try local search: add any edge, if girth still >= 8 keep, else remove an edge to fix
def local_search(seed, target=37, iters=20000):
    random.seed(seed)
    n = 19
    adj = [set() for _ in range(n)]
    edges = set()

    for it in range(iters):
        # random action
        u,v = sorted(random.sample(range(n),2))
        if (u,v) in edges:
            # maybe remove
            if random.random() < 0.1:
                edges.remove((u,v))
                adj[u].discard(v); adj[v].discard(u)
        else:
            # try add
            # compute dist
            dist = {u:0}
            q = [u]
            ok = True
            for d in range(7):
                nq = []
                for x in q:
                    for y in adj[x]:
                        if y not in dist:
                            dist[y]=d+1
                            nq.append(y)
                q = nq
                if v in dist:
                    ok = False; break
            if ok:
                edges.add((u,v))
                adj[u].add(v); adj[v].add(u)
                if len(edges) >= target:
                    return list(edges)
    return list(edges)

